INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (17, 'Jahitan lurus tidak terbentuk dengan benar', 'Jahitan tidak rapi, panjang stitch berubah, atau hasil jahitan tidak konsisten.', 'Ketegangan benang tidak sesuai, jarum atau benang tidak cocok, atau mekanisme pembentukan jahitan perlu diperiksa.', 'Periksa pemasangan jarum dan benang, sesuaikan ketegangan benang, periksa panjang stitch, lalu lakukan uji jahit pada material yang digunakan.', 'Matikan mesin dan lepaskan sumber daya sebelum melakukan pemeriksaan atau penyetelan pada area jarum dan hook.', 'Data spesifikasi JUKI DDL-7300 dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (17, 'Benang atas sering putus', 'Benang atas putus berulang saat mesin dijalankan.', 'Ketegangan benang terlalu tinggi, jalur benang tidak benar, jarum rusak atau tidak sesuai, atau terdapat bagian yang kasar pada jalur benang.', 'Periksa jalur pemasangan benang, kurangi ketegangan bila berlebihan, ganti jarum yang rusak, dan periksa bagian jalur benang yang bersentuhan dengan benang.', 'Matikan mesin sebelum menyentuh jarum, tension mechanism, atau jalur benang.', 'Data spesifikasi JUKI DDL-7300 dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (17, 'Benang bawah sering putus atau tidak stabil', 'Benang bobbin putus, tersangkut, atau jahitan bawah tidak stabil.', 'Bobbin tidak terpasang dengan benar, ketegangan benang bobbin tidak sesuai, atau area hook kotor.', 'Periksa pemasangan bobbin, bersihkan area hook, periksa ketegangan benang bobbin, dan pastikan bobbin berputar dengan lancar.', 'Matikan mesin sebelum membersihkan area hook dan bobbin.', 'Data spesifikasi JUKI DDL-7300 dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (17, 'Jahitan loncat atau tidak terbentuk', 'Beberapa stitch tidak terbentuk dan hasil jahitan terlihat terputus.', 'Jarum bengkok atau tumpul, pemasangan jarum tidak tepat, timing needle-hook tidak sesuai, atau benang tidak terpasang dengan benar.', 'Periksa dan ganti jarum bila diperlukan, pastikan orientasi jarum benar, periksa pemasangan benang, dan lakukan pemeriksaan timing hook oleh teknisi bila diperlukan.', 'Matikan mesin sebelum mengganti jarum atau memeriksa area hook.', 'Data spesifikasi JUKI DDL-7300 dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (17, 'Panjang jahitan tidak sesuai', 'Panjang stitch lebih pendek atau lebih panjang dari pengaturan yang diinginkan.', 'Pengaturan stitch length berubah, mekanisme drop feed kotor atau tidak bergerak normal, atau tekanan presser foot tidak sesuai.', 'Periksa pengaturan panjang stitch, bersihkan area feed dog, periksa gerakan drop feed, dan sesuaikan tekanan presser foot sesuai material.', 'Matikan mesin sebelum membersihkan feed dog atau melakukan penyetelan mekanis.', 'Data spesifikasi JUKI DDL-7300 dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (17, 'Kain tidak bergerak stabil saat dijahit', 'Kain tersendat, bergeser, atau feed tidak konsisten selama proses jahit.', 'Feed dog kotor atau aus, tekanan presser foot tidak sesuai, atau permukaan material tidak sesuai dengan pengaturan mesin.', 'Bersihkan feed dog, periksa tekanan presser foot, pastikan material terposisikan dengan benar, dan periksa kondisi komponen feed jika masalah berlanjut.', 'Matikan mesin sebelum membersihkan atau memeriksa mekanisme feed.', 'Data spesifikasi JUKI DDL-7300 dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (17, 'Jarum patah atau posisi jarum tidak normal', 'Jarum patah, bengkok, menyentuh presser foot atau needle plate, atau posisi jarum berubah.', 'Jarum tidak sesuai, pemasangan kurang tepat, material terlalu berat untuk konfigurasi, atau terjadi gangguan pada area needle-hook.', 'Ganti jarum dengan ukuran yang sesuai, pasang dengan orientasi yang benar, periksa posisi presser foot dan needle plate, serta periksa area hook bila terjadi benturan.', 'Matikan mesin dan pastikan pedal tidak aktif sebelum mengganti atau memeriksa jarum.', 'Data spesifikasi JUKI DDL-7300 dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (17, 'Pelumasan atau gerakan mesin tidak normal', 'Mesin terdengar kasar, bergerak berat, terlalu panas, atau terdapat indikasi pelumasan tidak normal.', 'Level oli tidak sesuai, sistem pelumasan otomatis tidak bekerja normal, area mekanisme kotor, atau terdapat komponen yang aus.', 'Periksa level dan kondisi oli, pastikan sistem pelumasan bekerja, bersihkan area yang diperlukan, dan hentikan penggunaan untuk pemeriksaan teknisi jika suara atau gerakan tetap tidak normal.', 'Matikan mesin dan lepaskan sumber daya sebelum memeriksa sistem pelumasan atau bagian mekanis yang bergerak.', 'Data spesifikasi JUKI DDL-7300 dan panduan pemeriksaan umum.');
